ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_capability_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','audit.read','interview.read','interview.write','interview_policy.manage','assessment.request','assessment.read','assessment.input.approve','assessment.publish','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE access_grant DROP CONSTRAINT access_grant_capability_check;
ALTER TABLE access_grant ADD CONSTRAINT access_grant_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage','audit.read','interview.read','interview.write','interview_policy.manage','assessment.request','assessment.read','assessment.input.approve','assessment.publish','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_category_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_category_check CHECK((((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write','sensitive.export') AND purpose='organization_management') OR (category='audit' AND capability IN('access_grant.manage','audit.read') AND purpose='security_administration') OR (purpose='interview_followup' AND ((category='metadata' AND capability IN('interview.read','interview.write','interview_policy.manage','assessment.request','assessment.read','assessment.input.approve','assessment.publish','sensitive.export')) OR (category IN('shared','manager_private','hr_confidential') AND capability IN('note.read','note.write','note.publish','sensitive.export')) OR (category='shared' AND capability IN('action.read','action.write'))))) OR (category='financial' AND purpose='compensation_management' AND capability IN('compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','sensitive.export'))) AND capability<>'access_grant.manage');
ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_purpose_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_purpose_check CHECK(purpose IN('organization_management','security_administration','interview_followup','compensation_management'));
ALTER TABLE access_grant DROP CONSTRAINT access_grant_category_check;
ALTER TABLE access_grant ADD CONSTRAINT access_grant_category_check CHECK((((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write','sensitive.export') AND purpose='organization_management') OR (category='audit' AND capability IN('access_grant.manage','audit.read') AND purpose='security_administration') OR (purpose='interview_followup' AND ((category='metadata' AND capability IN('interview.read','interview.write','interview_policy.manage','assessment.request','assessment.read','assessment.input.approve','assessment.publish','sensitive.export')) OR (category IN('shared','manager_private','hr_confidential') AND capability IN('note.read','note.write','note.publish','sensitive.export')) OR (category='shared' AND capability IN('action.read','action.write'))))) OR (category='financial' AND purpose='compensation_management' AND capability IN('compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','sensitive.export'))));
ALTER TABLE audit_event DROP CONSTRAINT audit_event_operation_check;
ALTER TABLE audit_event ADD CONSTRAINT audit_event_operation_check CHECK(operation IN('OP-ORG-01','OP-ORG-02','OP-ORG-03','OP-ORG-04','OP-ORG-05','OP-ORG-07','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-04','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND','OP-INT-01','OP-INT-02','OP-INT-03','OP-INT-04','OP-INT-05','OP-INT-06','OP-INT-07','OP-INT-08','OP-SEC-05','OP-COMP-01','OP-COMP-02','OP-COMP-03','OP-COMP-04','OP-COMP-05','OP-BONUS-01','OP-BONUS-02','OP-BONUS-03','OP-BONUS-04','OP-BONUS-05','OP-BONUS-06','OP-BONUS-07','OP-BONUS-08','OP-AI-01','OP-AI-02','OP-AI-03','OP-AI-04','OP-AI-05','OP-AI-06','OP-AI-07','OP-AI-08'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_action_check;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_action_check CHECK(action IN('','pii.write','access_grant.manage','audit.read','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','interview_policy.manage','assessment.input.approve','assessment.publish'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_check2;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_check2 CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','audit.read','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','interview_policy.manage') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL));
CREATE INDEX audit_event_page ON audit_event(org_id,recorded_at DESC,id DESC);
CREATE TABLE key_rewrap_job(org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('pii','interview','financial')),state TEXT NOT NULL CHECK(state IN('migrating','ready','blocked')),target_kek_id TEXT NOT NULL,target_kek_version BIGINT NOT NULL CHECK(target_kek_version>0),manifest_digest BYTEA NOT NULL CHECK(octet_length(manifest_digest)=32),completed BIGINT NOT NULL DEFAULT 0 CHECK(completed>=0),started_at TIMESTAMPTZ(6) NOT NULL,updated_at TIMESTAMPTZ(6) NOT NULL,PRIMARY KEY(org_id,domain),FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE key_rewrap_audit(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('pii','interview','financial')),target_kek_id TEXT NOT NULL,target_kek_version BIGINT NOT NULL,manifest_digest BYTEA NOT NULL CHECK(octet_length(manifest_digest)=32),completed BIGINT NOT NULL,actor_uid BIGINT NOT NULL CHECK(actor_uid BETWEEN 0 AND 4294967295),actor_host_hash BYTEA NOT NULL CHECK(octet_length(actor_host_hash)=32),recorded_at TIMESTAMPTZ(6) NOT NULL,FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE key_rewrap_approval_audit(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,domain TEXT NOT NULL CHECK(domain IN('pii','interview','financial')),target_kek_id TEXT NOT NULL,target_kek_version BIGINT NOT NULL CHECK(target_kek_version>0),manifest_digest BYTEA NOT NULL CHECK(octet_length(manifest_digest)=32),kind TEXT NOT NULL CHECK(kind IN('start','renew')),recorded_at TIMESTAMPTZ(6) NOT NULL,FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE FUNCTION key_rewrap_write_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE job_state TEXT; job_kek_id TEXT; job_kek_version BIGINT; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id || ':' || TG_ARGV[0],0)); SELECT state,target_kek_id,target_kek_version INTO job_state,job_kek_id,job_kek_version FROM key_rewrap_job WHERE org_id=NEW.org_id AND domain=TG_ARGV[0]; IF FOUND AND (job_state<>'ready' OR job_kek_id<>NEW.kek_id OR job_kek_version<>NEW.kek_version) THEN RAISE EXCEPTION 'key maintenance active' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER rewrap_block_encrypted_payload BEFORE INSERT ON encrypted_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('pii');
CREATE TRIGGER rewrap_block_organizational_payload BEFORE INSERT ON organizational_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('pii');
CREATE TRIGGER rewrap_block_interview_payload BEFORE INSERT ON interview_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('interview');
CREATE TRIGGER rewrap_block_assessment_payload BEFORE INSERT ON assessment_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('interview');
CREATE TRIGGER rewrap_block_compensation_payload BEFORE INSERT ON compensation_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('financial');
CREATE TRIGGER rewrap_block_bonus_payload BEFORE INSERT ON bonus_payload FOR EACH ROW EXECUTE FUNCTION key_rewrap_write_guard('financial');
CREATE TABLE general_export_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN('organization_management','interview_followup')),key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),export_id TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ(6) NOT NULL,PRIMARY KEY(org_id,subject_id,purpose,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id));
CREATE TABLE audit_outbox(event_id TEXT PRIMARY KEY REFERENCES audit_event(id),org_id TEXT,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','inflight','acked')),attempt BIGINT NOT NULL DEFAULT 0 CHECK(attempt>=0),available_at TIMESTAMPTZ(6) NOT NULL,claim_token TEXT,claim_until TIMESTAMPTZ(6),receipt_id TEXT,receipt_digest BYTEA CHECK(receipt_digest IS NULL OR octet_length(receipt_digest)=32),acked_at TIMESTAMPTZ(6),CHECK((state='pending' AND claim_token IS NULL AND claim_until IS NULL AND receipt_id IS NULL AND receipt_digest IS NULL AND acked_at IS NULL) OR (state='inflight' AND claim_token IS NOT NULL AND claim_until IS NOT NULL AND receipt_id IS NULL AND receipt_digest IS NULL AND acked_at IS NULL) OR (state='acked' AND claim_token IS NULL AND claim_until IS NULL AND receipt_id IS NOT NULL AND receipt_digest IS NOT NULL AND acked_at IS NOT NULL)));
INSERT INTO audit_outbox(event_id,org_id,available_at) SELECT id,org_id,recorded_at FROM audit_event;
CREATE INDEX audit_outbox_delivery ON audit_outbox(state,available_at,event_id);
CREATE TABLE backup_restore_audit(id TEXT PRIMARY KEY,archive_digest BYTEA NOT NULL CHECK(octet_length(archive_digest)=32),actor_uid BIGINT NOT NULL CHECK(actor_uid BETWEEN 0 AND 4294967295),actor_host_hash BYTEA NOT NULL CHECK(octet_length(actor_host_hash)=32),revoked_sessions BIGINT NOT NULL CHECK(revoked_sessions>=0),recorded_at TIMESTAMPTZ(6) NOT NULL);
